// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "could you add a option to export the tables as PNG"
// Changes: Draws a table (header row + first column as row headers) onto a canvas and returns it as a PNG blob.
//          Returns the blob and its CSS width (the bitmap is drawn at 2× for sharpness).
//          Light theme so the image fits into documents; LL conflicts are highlighted red.

export type PngTable = { title: string; header: string[]; rows: string[][] }

const FONT = 'ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace'
const PAD_X = 10
const ROW_H = 28
const MARGIN = 16
const TITLE_H = 34
const MAX_CANVAS = 16000

export async function tableToPng(t: PngTable): Promise<{ blob: Blob; width: number }> {
  const measure = document.createElement('canvas').getContext('2d')!
  const width = (text: string, bold: boolean) => {
    measure.font = `${bold ? 'bold ' : ''}14px ${FONT}`
    return measure.measureText(text).width
  }
  const cols = t.header.map((h, c) =>
    Math.ceil(Math.max(28, width(h, true), ...t.rows.map((r) => width(r[c] ?? '', c === 0 || (r[c] ?? '').includes(',')))) + PAD_X * 2),
  )
  const tableW = cols.reduce((s, w) => s + w, 0)
  const w = Math.max(tableW, width(t.title, true) + 4) + MARGIN * 2
  const h = TITLE_H + ROW_H * (t.rows.length + 1) + MARGIN * 2
  const scale = Math.max(1, Math.min(2, MAX_CANVAS / w, MAX_CANVAS / h))

  const canvas = document.createElement('canvas')
  canvas.width = Math.round(w * scale)
  canvas.height = Math.round(h * scale)
  const ctx = canvas.getContext('2d')!
  ctx.scale(scale, scale)
  ctx.fillStyle = '#ffffff'
  ctx.fillRect(0, 0, w, h)

  ctx.fillStyle = '#18181b'
  ctx.font = `bold 16px ${FONT}`
  ctx.textBaseline = 'middle'
  ctx.fillText(t.title, MARGIN, MARGIN + TITLE_H / 2 - 4)

  const top = MARGIN + TITLE_H
  const all = [t.header, ...t.rows]
  all.forEach((row, r) => {
    let x = MARGIN
    const y = top + r * ROW_H
    cols.forEach((cw, c) => {
      const text = row[c] ?? ''
      const head = r === 0 || c === 0
      const conflict = !head && text.includes(',')
      if (head || conflict) {
        ctx.fillStyle = conflict ? '#fee2e2' : '#f4f4f5'
        ctx.fillRect(x, y, cw, ROW_H)
      }
      ctx.font = `${head || conflict ? 'bold ' : ''}14px ${FONT}`
      ctx.fillStyle = conflict ? '#b91c1c' : head ? '#18181b' : '#3730a3'
      ctx.textAlign = c === 0 ? 'left' : 'center'
      ctx.fillText(text, c === 0 ? x + PAD_X : x + cw / 2, y + ROW_H / 2 + 1)
      x += cw
    })
  })

  ctx.strokeStyle = '#d4d4d8'
  ctx.lineWidth = 1
  ctx.beginPath()
  for (let r = 0; r <= all.length; r++) {
    ctx.moveTo(MARGIN, top + r * ROW_H + 0.5)
    ctx.lineTo(MARGIN + tableW, top + r * ROW_H + 0.5)
  }
  let x = MARGIN
  for (let c = 0; c <= cols.length; c++) {
    ctx.moveTo(x + 0.5, top)
    ctx.lineTo(x + 0.5, top + all.length * ROW_H)
    x += cols[c] ?? 0
  }
  ctx.stroke()

  return new Promise((resolve, reject) => canvas.toBlob((b) => (b ? resolve({ blob: b, width: w }) : reject(new Error('PNG sa nepodarilo vytvoriť'))), 'image/png'))
}
